#pragma once
// Wire-indexed fused weighted LUT for rPhiFitter
//
// LUT index = wire (ap_uint<10>), 0..NWIRES[ax]-1
// cos2w_wire_lut[ax][wire] = cos²(wire*WIRE_STEP[ax]) * W[ax]
// sin2w_wire_lut[ax][wire] = sin²(wire*WIRE_STEP[ax]) * W[ax]
// cossin_wire_lut[ax][wire]= cos*sin(wire*WIRE_STEP[ax]) * W[ax]
// cosRW_wire_lut[ax][wire] = cos(wire*WIRE_STEP[ax]) * RW[ax]
// sinRW_wire_lut[ax][wire] = sin(wire*WIRE_STEP[ax]) * RW[ax]
//
// One-order Taylor correction for driftPhi:
//   c2w = c2w0 + (-2*csw0)         * delta
//   s2w = s2w0 + ( 2*csw0)         * delta
//   csw = csw0 + ( c2w0 - s2w0)    * delta
//   cRW = cRW0 + (-sRW0)            * delta
//   sRW = sRW0 + ( cRW0)            * delta
// where delta = +driftPhi (lr==2) or -driftPhi (lr==1) or 0 (lr==0/3 or T0==9999)
//
// ax=0 SL0: NWIRES=160, WIRE_STEP=0.0392699081698724
//        W=3521.636150712992, RW=69728.395784117252
// ax=1 SL2: NWIRES=192, WIRE_STEP=0.0327249234748937
//        W=3906.175782160458, RW=156872.019411563990
// ax=2 SL4: NWIRES=256, WIRE_STEP=0.0245436926061703
//        W=3907.949433251131, RW=242292.864861570124
// ax=3 SL6: NWIRES=320, WIRE_STEP=0.0196349540849362
//        W=3906.237499478611, RW=327498.951956286735
// ax=4 SL8: NWIRES=384, WIRE_STEP=0.0163624617374468
//        W=3906.273439599888, RW=412814.977096916235

#include "cdc2dfit_kernel.h"

