// ─────────────────────────────────────────────────────
// call_wire_fused_lut
//   wire, ax → base values (c2w0,s2w0,csw0,cRW0,sRW0)
//   then apply 1st-order Taylor if delta != 0
// ─────────────────────────────────────────────────────
static inline void call_wire_fused_lut(
    ap_uint<10>        wire,
    int                ax,
    fixed_type_general delta,   // +driftPhi, -driftPhi, or 0
    fixed_type_general &c2w,
    fixed_type_general &s2w,
    fixed_type_general &csw,
    fixed_type_general &cRW,
    fixed_type_general &sRW
) {
#pragma HLS INLINE
#pragma HLS BIND_STORAGE variable=cos2w_wire_lut  type=ROM_NP impl=LUTRAM
#pragma HLS BIND_STORAGE variable=sin2w_wire_lut  type=ROM_NP impl=LUTRAM
#pragma HLS BIND_STORAGE variable=cossin_wire_lut type=ROM_NP impl=LUTRAM
#pragma HLS BIND_STORAGE variable=cosRW_wire_lut  type=ROM_NP impl=LUTRAM
#pragma HLS BIND_STORAGE variable=sinRW_wire_lut  type=ROM_NP impl=LUTRAM

    int widx = (int)wire;
    if (widx < 0)                widx = 0;
    if (widx >= WIRE_LUT_MAX_WIRE) widx = WIRE_LUT_MAX_WIRE - 1;

    fixed_type_general c2w0 = cos2w_wire_lut [ax][widx];
    fixed_type_general s2w0 = sin2w_wire_lut [ax][widx];
    fixed_type_general csw0 = cossin_wire_lut[ax][widx];
    fixed_type_general cRW0 = cosRW_wire_lut [ax][widx];
    fixed_type_general sRW0 = sinRW_wire_lut [ax][widx];

    if (delta == FX_ZERO) {
        c2w = c2w0; s2w = s2w0; csw = csw0; cRW = cRW0; sRW = sRW0;
        return;
    }

    // 1st-order Taylor: f(phi0+delta) ≈ f(phi0) + f'(phi0)*delta
    // d(cos²W)/dphi   = -2*cossin*W  = -2*csw0
    // d(sin²W)/dphi   = +2*cossin*W  = +2*csw0
    // d(cossin*W)/dphi= (cos²-sin²)*W = (c2w0-s2w0)
    // d(cos*RW)/dphi  = -sin*RW      = -sRW0
    // d(sin*RW)/dphi  = +cos*RW      = +cRW0
    c2w = c2w0 + fixed_type_general(-2) * csw0          * delta;
    s2w = s2w0 + fixed_type_general( 2) * csw0          * delta;
    csw = csw0 + (c2w0 - s2w0)                          * delta;
    cRW = cRW0 + (-sRW0)                                 * delta;
    sRW = sRW0 + ( cRW0)                                 * delta;
}